POINTS = [
    (0.00, 0.15), (0.23, 0.15), (0.23, 0.02), (0.00, 0.02),
    (0.10, -0.02), (0.33, -0.02), (0.33, -0.15), (0.10, -0.15),
]


def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])


def convex_hull(points):
    pts = sorted(set(points))
    if len(pts) <= 2:
        return pts
    lower = []
    for p in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]


hull = convex_hull(POINTS)
print("n", len(hull))
print("hull", [tuple(round(v, 3) for v in p) for p in hull])

