import math

G = 9.81
Z = 0.85
W = math.sqrt(G / Z)
DT = 0.002
MASS = 45.0
GAIN = 2.2
FOOT_HALF = 0.115
TORSO_INERTIA = 1.8
MAX_TORSO_ACC = 12.0
SWING_TIME = 0.30
MAX_STEP = 0.45
ANKLE_LIMIT = 0.06
HIP_LIMIT = 0.12


def strategy_for(error):
    magnitude = abs(error)
    if magnitude <= ANKLE_LIMIT:
        return "ankle"
    if magnitude <= HIP_LIMIT:
        return "hip"
    return "step"


def hip_shift():
    return TORSO_INERTIA * MAX_TORSO_ACC / (MASS * G)


def authority():
    return FOOT_HALF + hip_shift()


def hold(raw):
    ankle = min(FOOT_HALF, max(-FOOT_HALF, raw))
    hip = min(hip_shift(), max(-hip_shift(), raw - ankle))
    return (ankle, hip)


def run(impulse, duration=2.0):
    x, v = 0.0, 0.0
    support = 0.0
    peak = 0.0
    worst = "ankle"
    rank = {"ankle": 0, "hip": 1, "step": 2}
    landing, touchdown, reachable = None, 0.0, True
    for i in range(int(round(duration / DT))):
        t = i * DT
        if i == int(round(0.5 / DT)):
            v += impulse / MASS
        if landing is not None and t >= touchdown:
            support, landing = landing, None
        xi = x + v / W
        error = xi - support
        peak = max(peak, abs(error))
        raw = GAIN * error
        if abs(raw) > authority() and landing is None:
            held = support + (authority() if error >= 0.0 else -authority())
            target = held + (xi - held) * math.exp(W * SWING_TIME)
            if abs(target - support) > MAX_STEP:
                reachable = False
            landing = support + min(MAX_STEP, max(-MAX_STEP, target - support))
            touchdown = t + SWING_TIME
        mode = "step" if landing is not None else strategy_for(error)
        if rank[mode] > rank[worst]:
            worst = mode
        ankle, hip = hold(raw)
        v += (G / Z) * (x - (support + ankle + hip)) * DT
        x += v * DT
    return (round(peak, 4), worst, reachable and abs(v) < 0.05)


