DT = 0.002
THRESHOLD = 5.0
PERSIST = 0.02


class CollisionMonitor:
    def __init__(self, joints):
        self.timers = {j: 0.0 for j in joints}

    def update(self, expected, measured):
        triggered = []
        for joint in self.timers:
            residual = abs(measured[joint] - expected[joint])
            if residual > THRESHOLD:
                self.timers[joint] += DT
            else:
                self.timers[joint] = 0.0
            if self.timers[joint] >= PERSIST:
                triggered.append(joint)
        return triggered


