ENERGY_LIMIT = 0.5
SAFE_DISTANCE = 1.5


def stopping_distance(v):
    return v * REACTION + (v * v) / (2.0 * MAX_DECEL)


def scale_for_distance(v, distance):
    stop = stopping_distance(v)
    if distance >= SAFE_DISTANCE:
        return v
    if distance <= stop:
        return 0.0
    span = SAFE_DISTANCE - stop
    return v * (distance - stop) / span


def energy_ok(v):
    return 0.5 * EFFECTIVE_MASS * v * v <= ENERGY_LIMIT


