import math

DT = 0.002
LIMITS = {"hip": (math.radians(-120.0), math.radians(45.0)),
          "knee": (math.radians(8.0), math.radians(150.0)),
          "ankle": (math.radians(-70.0), math.radians(60.0))}
MAX_RATE = 6.0
BALANCE_GAIN = 2.2


def balance_correction(dcm, dcm_ref):
    return BALANCE_GAIN * (dcm - dcm_ref)


def guard(previous, command):
    out = {}
    for name, value in command.items():
        if not math.isfinite(value):
            out[name] = previous[name]
            continue
        low, high = LIMITS[name]
        target = min(high, max(low, value))
        delta = target - previous[name]
        max_delta = MAX_RATE * DT
        if delta > max_delta:
            target = previous[name] + max_delta
        elif delta < -max_delta:
            target = previous[name] - max_delta
        out[name] = target
    return out


prev = {"hip": 0.0, "knee": math.radians(20.0), "ankle": 0.0}
cmd = {"hip": math.radians(-200.0), "knee": math.radians(2.0), "ankle": 0.4}
print("balance", round(balance_correction(0.05, 0.0), 4))
print("guarded", {k: round(math.degrees(v), 3) for k, v in guard(prev, cmd).items()})

