ABORT = {
    "stand": "hold",
    "walk": "finish_step",
    "reach": "retract_arm",
    "handover": "retract_arm",
    "recover": "hold",
}


class Behavior:
    def __init__(self):
        self.state = "stand"

    def step(self, goal, estimate, mode):
        if mode in ("fall", "estop"):
            action = ABORT[self.state]
            self.state = "recover" if mode == "fall" else "stand"
            return (self.state, action)
        if mode == "stop":
            return (self.state, ABORT[self.state])
        if goal == "walk" and estimate["support"] == "double" and estimate["dcm_error"] < 0.05:
            self.state = "walk"
        elif goal in ("reach", "handover") and estimate["reachable"]:
            self.state = goal
        else:
            self.state = "stand"
        return (self.state, "execute")


b = Behavior()
good = {"support": "double", "dcm_error": 0.01, "reachable": True}
print(b.step("walk", good, "run"))
print(b.step("reach", good, "run"))
print(b.step("reach", good, "stop"))
